import {safe,keyword} from './experience.js';
let dispose=()=>{};
export function bindMoodStudio(root,albums){
 dispose();const room=root.querySelector('.mood-room');if(!room)return;
 const events=new AbortController(),opt={signal:events.signal},reduce=matchMedia('(prefers-reduced-motion: reduce)'),board=room.querySelector('.mood-collage');let frame=0,scene=0;
 board.querySelectorAll('.mood-fragment').forEach(n=>n.remove());
 const controls=document.createElement('div');controls.className='mood-studio-controls';controls.innerHTML='<div role="group" aria-label="Composição visual"><button data-remix-mood>Trocar as cores ↻</button><button data-mood-layout aria-pressed="false">Alinhar os discos ▦</button><button data-mood-motion aria-pressed="true">Pausar movimento</button></div>';board.before(controls);board.setAttribute('aria-label','Discos sobre um fundo de cores interativo');
 let moving=true;try{moving=localStorage.getItem('meeting.points.mood.motion')!=='false';}catch{}
 const canvas=document.createElement('canvas');canvas.className='mood-particles';canvas.setAttribute('aria-hidden','true');board.prepend(canvas);
 const lexicon=room.classList.contains('mood-energia')?['PULSO','ATRITO','ASCENSÃO']:room.classList.contains('mood-curiosidade')?['DESVIO','DETALHE','DESCOBERTA']:['AR','ESPAÇO','RESPIRO'];const constellation=document.createElement('div');constellation.className='mood-constellation';constellation.setAttribute('aria-hidden','true');constellation.innerHTML=lexicon.map((word,i)=>`<span style="--i:${i}">${word}</span>`).join('');board.append(constellation);
 const ctx=canvas.getContext?.('2d');let width=1,height=1,x=.5,y=.5,tx=.5,ty=.5,power=0,targetPower=0;
 const palettes=[[227,285,315],[245,310,225],[205,255,300]];
 const draw=()=>{if(!ctx)return;ctx.clearRect(0,0,width,height);const colors=palettes[scene];ctx.lineWidth=.8;for(let band=0;band<18;band++){ctx.strokeStyle=`hsla(${colors[band%3]},52%,66%,.16)`;ctx.beginPath();for(let cx=-20;cx<width+24;cx+=8){const cy=height*(band/17)+Math.sin(cx/160+band*.23+scene)*46+Math.cos(cx/230-band*.19)*24;const d=Math.hypot(cx-x*width,cy-y*height),pull=Math.exp(-d*d/60000)*power;const py=cy+Math.sin(cx/100+band*.3)*pull*44;cx===-20?ctx.moveTo(cx,py):ctx.lineTo(cx,py);}ctx.stroke();}for(let row=0;row<height;row+=19)for(let col=0;col<width;col+=19){const d=Math.hypot(col-x*width,row-y*height),force=Math.max(0,1-d/280)*power;const wave=(Math.sin(col/180+row/220+scene)+1)/2;const hue=colors[Math.floor(wave*2.99)%3];ctx.fillStyle=`hsla(${hue},60%,${74-force*5}%,${.12+wave*.18+force*.2})`;ctx.beginPath();ctx.arc(col+Math.sin(row/90+scene+x*power*3)*18+force*(col-x*width)*.12,row+Math.cos(col/130+scene+y*power*3)*25+force*(row-y*height)*.12,1.1+wave*1.1+force*3,0,Math.PI*2);ctx.fill();}};
 const tick=()=>{frame=0;x+=(tx-x)*.07;y+=(ty-y)*.07;power+=(targetPower-power)*.065;board.style.setProperty('--pointer-x',x*100+'%');board.style.setProperty('--pointer-y',y*100+'%');draw();if(Math.abs(tx-x)+Math.abs(ty-y)+Math.abs(targetPower-power)>.003)frame=requestAnimationFrame(tick);};
 const schedule=()=>{if(!frame)frame=requestAnimationFrame(tick);};
 const resize=()=>{const r=board.getBoundingClientRect();width=Math.max(1,r.width);height=Math.max(1,r.height);const dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0);draw();};
 const resizeObserver=typeof ResizeObserver!=='undefined'?new ResizeObserver(resize):null;resizeObserver?.observe(board);resize();
 const setMotion=on=>{moving=on&&!reduce.matches;room.classList.toggle('mood-moving',moving);const b=controls.querySelector('[data-mood-motion]');b.setAttribute('aria-pressed',String(moving));b.textContent=moving?'Pausar movimento':'Ativar movimento';if(!moving){targetPower=0;cancelAnimationFrame(frame);frame=0;power=0;draw();}};setMotion(moving);
 controls.querySelector('[data-mood-motion]').addEventListener('click',()=>{setMotion(!moving);try{localStorage.setItem('meeting.points.mood.motion',String(moving));}catch{}},opt);
 controls.querySelector('[data-remix-mood]').addEventListener('click',()=>{scene=(scene+1)%3;board.dataset.composition=String(scene);board.style.setProperty('--field-a',['#dce5ff','#e7dffa','#d9eef2'][scene]);board.style.setProperty('--field-b',['#f3e0ed','#eee4f6','#e8e0f6'][scene]);board.style.setProperty('--mood-hue','0deg');draw();},opt);
 controls.querySelector('[data-mood-layout]').addEventListener('click',e=>{const grid=room.classList.toggle('mood-grid-view');e.currentTarget.setAttribute('aria-pressed',String(grid));e.currentTarget.textContent=grid?'Soltar os discos ◇':'Alinhar os discos ▦';resize();},opt);
 board.addEventListener('pointermove',e=>{if(!moving||reduce.matches||e.pointerType==='touch')return;const r=board.getBoundingClientRect();tx=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));ty=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));targetPower=1;schedule();},opt);
 board.addEventListener('pointerleave',()=>{targetPower=0;if(moving)schedule();},opt);board.addEventListener('pointerdown',e=>{if(reduce.matches)return;const r=board.getBoundingClientRect(),echo=document.createElement('i');echo.className='mood-echo';echo.style.left=e.clientX-r.left+'px';echo.style.top=e.clientY-r.top+'px';board.append(echo);echo.addEventListener('animationend',()=>echo.remove(),{once:true});},opt);
 reduce.addEventListener('change',()=>{if(reduce.matches)setMotion(false);},opt);
 room.querySelectorAll('.mood-listen>div').forEach(row=>{const link=row.querySelector('a'),a=albums.find(a=>link.getAttribute('href')==='#album/'+a.id);if(!a)return;row.classList.add('mood-listen-card');const cover=document.createElement('img');cover.src=a.cover;cover.alt='';cover.loading='lazy';cover.width=400;cover.height=400;link.prepend(cover);const facts=document.createElement('div');facts.className='mood-record-facts';facts.innerHTML=keyword(a.genre,'genre')+'<span> · </span>'+keyword(String(a.release).slice(0,4),'year');row.append(facts);});
 const session=room.classList.contains('mood-energia')?['fatboy-brighton-2002','Fatboy Slim · Brighton']:room.classList.contains('mood-curiosidade')?['justice-iris','Justice · IRIS']:['porter-secret-sky-2021','Porter Robinson · Secret Sky'];
 const related=document.createElement('div');related.className='mood-connections';related.innerHTML=`<span class="eyebrow">CONTINUE EXPLORANDO</span><a href="#tv/${session[0]}">${session[1]} ↗</a>`;room.append(related);
 dispose=()=>{events.abort();resizeObserver?.disconnect();cancelAnimationFrame(frame);};
}
